// Example 8: EJB that attempts to open a file selection dialog using AWT in business method
import javax.ejb.Stateless;
import java.awt.FileDialog;
import java.awt.Frame;

@Stateless
public class FileSelectionBean {

    public String selectFile() {
        FileDialog dialog = new FileDialog((Frame) null, "Select a file");
