// 9. Invoking methods with boxed primitives repeatedly in performance-sensitive code
public class Utility {
    public long sumDates(List<Long> timestamps) {
        long total = 0;
        for (Long ts : timestamps) { // autoboxing in list
            total += ts; // unboxing
