import com.fasterxml.jackson.databind.ObjectMapper;
import java.io.IOException;

public class Example9 {
    public static void main(String[] args) {
        ObjectMapper mapper = new ObjectMapper();
        String invalidJson = "{ invalid json }";

        try {
